// fixButtons.js
// This script cleans up malformed <Button> tags generated by previous replacements
// It also converts any remaining <button> tags to <Button> with required props.
const fs = require('fs');
const path = require('path');

const srcDir = path.resolve(__dirname, '..', 'src', 'components');

function fixContent(content) {
  // 1. Replace raw <button> tags
  content = content.replace(/<button([^>]*)>([\s\S]*?)<\/button>/g, (match, attrs, inner) => {
    let newAttrs = attrs.trim();
    // add size and variant if missing
    if (!/\bsize\s*=/.test(newAttrs)) newAttrs += ' size="md"';
    if (!/\bvariant\s*=/.test(newAttrs)) newAttrs += ' variant="ghost"';
    return `<Button${newAttrs ? ' ' + newAttrs : ''}>${inner}</Button>`;
  });
  // 2. Fix malformed onClick attribute introduced earlier
  // pattern: onClick={() = size="md" variant="ghost">   => onClick={() =>
  content = content.replace(/onClick\(\)\s*=\s*size=\"md\"\s*variant=\"ghost\"\>/g, 'onClick={() =>');
  // 3. Remove stray "=" before size/variant in Button opening tags
  // e.g., <Button size="md" variant="ghost" ...> is fine, but sometimes we have "= size=..."
  // Already handled by step 1, but clean any leftover "= size"
  content = content.replace(/<Button\s+([^>]*?)=\s*size=/g, '<Button $1 size=');
  // 4. Ensure import of Button exists (will be added later per file)
  return content;
}

function processFile(filePath) {
  let code = fs.readFileSync(filePath, 'utf8');
  const original = code;
  code = fixContent(code);
  // Add import if missing
  if (!code.includes("import { Button }")) {
    const lines = code.split('\n');
    let lastImport = -1;
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].startsWith('import ')) lastImport = i;
    }
    const importStmt = "import { Button } from './ui';";
    if (lastImport >= 0) lines.splice(lastImport + 1, 0, importStmt);
    else lines.unshift(importStmt);
    code = lines.join('\n');
  }
  if (code !== original) {
    fs.writeFileSync(filePath, code, 'utf8');
  }
}

function walk(dir) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const e of entries) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p);
    else if (e.isFile() && p.endsWith('.tsx')) processFile(p);
  }
}

walk(srcDir);
console.log('Button cleanup complete');
